// --- 模拟 Vue 3 核心响应式 ---
let activeEffect = null;
const targetMap = new WeakMap();
const effectStack = [];

function track(target, key) {
  if (!activeEffect) return;
  let depsMap = targetMap.get(target);
  if (!depsMap) targetMap.set(target, (depsMap = new Map()));
  let dep = depsMap.get(key);
  if (!dep) depsMap.set(key, (dep = new Set()));
  dep.add(activeEffect);
  activeEffect.deps.add(dep); // 反向记录，便于 cleanup
}

function trigger(target, key, type) {
  const depsMap = targetMap.get(target);
  if (!depsMap) return;
  const dep = depsMap.get(key);
  const effectsToRun = new Set();
  if (dep) {
    dep.forEach(effect => {
      if (effect !== activeEffect) effectsToRun.add(effect);
    });
  }
  effectsToRun.forEach(effect => {
    if (effect.scheduler) {
      effect.scheduler(effect); // 走调度器，不直接执行
    } else {
      effect();
    }
  });
}

function effect(fn, options = {}) {
  const effectFn = () => {
    cleanup(effectFn); // 每次执行前清理旧依赖
    activeEffect = effectFn;
    effectStack.push(effectFn);
    const result = fn();
    effectStack.pop();
    activeEffect = effectStack[effectStack.length - 1];
    return result;
  };
  effectFn.deps = new Set();
  effectFn.scheduler = options.scheduler;
  effectFn.lazy = options.lazy;
  if (!options.lazy) effectFn();
  return effectFn;
}

function cleanup(effectFn) {
  effectFn.deps.forEach(dep => dep.delete(effectFn));
  effectFn.deps.clear();
}

function reactive(target) {
  return new Proxy(target, {
    get(obj, key, receiver) {
      track(obj, key);
      const result = Reflect.get(obj, key, receiver);
      if (result !== null && typeof result === 'object') {
        return reactive(result); // 惰性递归
      }
      return result;
    },
    set(obj, key, value, receiver) {
      const oldValue = obj[key];
      const result = Reflect.set(obj, key, value, receiver);
      if (oldValue !== value) trigger(obj, key, 'set');
      return result;
    },
    deleteProperty(obj, key) {
      const result = Reflect.deleteProperty(obj, key);
      trigger(obj, key, 'delete');
      return result;
    }
  });
}

function computed(getter) {
  let _dirty = true;
  let _value;
  const effectFn = effect(getter, {
    lazy: true,
    scheduler() {
      if (!_dirty) {
        _dirty = true;
        trigger(computedObj, 'value'); // 通知 computed 的消费者
      }
    }
  });
  const computedObj = {
    get value() {
      if (_dirty) {
        _value = effectFn();
        _dirty = false;
      }
      track(computedObj, 'value');
      return _value;
    }
  };
  return computedObj;
}

// --- 演示 ---
const state = reactive({ count: 0, nested: { deep: 1 } });

// effect 读取 state.count → track
let renderCount = 0;
const renderEffect = effect(() => {
  renderCount++;
  return state.count;
});
console.log('initial render:', renderCount); // 1

state.count = 1; // trigger → renderEffect 重跑 → renderCount = 2
console.log('after set:', renderCount); // 2

// 多次赋值只触发一次更新（去重）
state.count = 2;
state.count = 3;
console.log('after batch set:', renderCount); // 3（不是 5）

// computed 缓存
let computeCount = 0;
const doubled = computed(() => {
  computeCount++;
  return state.count * 2;
});
doubled.value; // 求值 → computeCount = 1
doubled.value; // 缓存命中 → computeCount 仍为 1
console.log('computeCount:', computeCount); // 1

// 新增属性（Vue 2 盲区，Vue 3 正常）
state.newKey = 'hello';
console.log('newKey:', state.newKey); // 触发 track，响应式
